command:
wait-for-it -t 120 mariadb:3306; wait-for-it -t 120 redis-cache:6379; wait-for-it -t 120 redis-queue:6379; ls -1 apps > sites/apps.txt; export start=`date +%s`; until [[ -n `grep -hs ^ sites/common_site_config.json | jq -r ".db_host // empty"` ]] && \
  [[ -n `grep -hs ^ sites/common_site_config.json | jq -r ".redis_cache // empty"` ]] && \
  [[ -n `grep -hs ^ sites/common_site_config.json | jq -r ".redis_queue // empty"` ]];
do
  echo "Waiting for sites/common_site_config.json to be created";
  sleep 5;
  if (( `date +%s`-start > 120 )); then
    echo "could not find sites/common_site_config.json with required keys";
    exit 1
  fi
done; echo "sites/common_site_config.json found"; if [[ -f sites/frontend/site_config.json ]]; then echo "site frontend exists"; exit 0; fi; bench new-site --mariadb-user-host-login-scope='%' --admin-password=admin --db-root-username=root --db-root-password='${secret:db_root_password}' --install-app erpnext --set-default frontend;
